pub export fn GPU_FillSupportedShaderFormats(props: SDL_PropertiesID) void {
    @setEvalBranchQuota(100000);
    var custom_shaders: bool = @"false" != 0;
    _ = &custom_shaders;
    if (SDL_GetBooleanProperty_REAL(props, "SDL.renderer.create.gpu.shaders_spirv", @"false" != 0)) {
        _ = SDL_SetBooleanProperty_REAL(props, "SDL.gpu.device.create.shaders.spirv", HAVE_SPIRV_SHADERS != 0);
        custom_shaders = @"true" != 0;
    }
    if (SDL_GetBooleanProperty_REAL(props, "SDL.renderer.create.gpu.shaders_dxil", @"false" != 0)) {
        _ = SDL_SetBooleanProperty_REAL(props, "SDL.gpu.device.create.shaders.dxil", HAVE_DXIL60_SHADERS != 0);
        custom_shaders = @"true" != 0;
    }
    if (SDL_GetBooleanProperty_REAL(props, "SDL.renderer.create.gpu.shaders_msl", @"false" != 0)) {
        _ = SDL_SetBooleanProperty_REAL(props, "SDL.gpu.device.create.shaders.msl", HAVE_METAL_SHADERS != 0);
        custom_shaders = @"true" != 0;
    }
    if (!custom_shaders) {
        _ = SDL_SetBooleanProperty_REAL(props, "SDL.gpu.device.create.shaders.private", HAVE_PRIVATE_SHADERS != 0);
        _ = SDL_SetBooleanProperty_REAL(props, "SDL.gpu.device.create.shaders.spirv", HAVE_SPIRV_SHADERS != 0);
        _ = SDL_SetBooleanProperty_REAL(props, "SDL.gpu.device.create.shaders.dxil", HAVE_DXIL60_SHADERS != 0);
        _ = SDL_SetBooleanProperty_REAL(props, "SDL.gpu.device.create.shaders.msl", HAVE_METAL_SHADERS != 0);
    }
}

