pub fn CompileShader(sources: [*c]const GPU_ShaderSources, device: ?*SDL_GPUDevice, stage: SDL_GPUShaderStage) callconv(.c) ?*SDL_GPUShader {
    @setEvalBranchQuota(100000);
    var sms: [*c]const GPU_ShaderModuleSource = null;
    _ = &sms;
    var formats: SDL_GPUShaderFormat = SDL_GetGPUShaderFormats_REAL(device);
    _ = &formats;
    if (formats == @as(SDL_GPUShaderFormat, SDL_GPU_SHADERFORMAT_INVALID)) {
        return null;
    } else if ((formats & (@as(c_uint, 1) << @intCast(@as(c_uint, 1)))) != 0) {
        sms = &sources.*.spirv;
    } else {
        _ = SDL_SetError_REAL("Unsupported GPU backend");
        return null;
    }
    var sci: SDL_GPUShaderCreateInfo = SDL_GPUShaderCreateInfo{
        .code_size = 0,
        .code = null,
        .entrypoint = null,
        .format = 0,
        .stage = @import("std").mem.zeroes(SDL_GPUShaderStage),
        .num_samplers = 0,
        .num_storage_textures = 0,
        .num_storage_buffers = 0,
        .num_uniform_buffers = 0,
        .props = 0,
    };
    _ = &sci;
    sci.code = sms.*.code;
    sci.code_size = sms.*.code_len;
    sci.format = sms.*.format;
    sci.entrypoint = "main";
    sci.num_samplers = sources.*.num_samplers;
    sci.num_uniform_buffers = sources.*.num_uniform_buffers;
    sci.stage = stage;
    return SDL_CreateGPUShader_REAL(device, &sci);
}
